const KEY='campusrelay-v1';
const seed=()=>({events:[{id:'e1',name:'Northstar Hackathon 2026',organizer:'Northstar Tech Society',category:'Hackathon',stage:'Shortlisted',url:'',registrationId:'NST-2048',dates:{'Registration deadline':'2026-10-11','Proposal deadline':'2026-10-17','Final round':'2026-10-24'},history:[{field:'Proposal deadline',old:'2026-10-15',value:'2026-10-17',source:'s2',at:'2026-10-13T09:00:00'}],journey:[{label:'Discovered',date:'2026-10-08',source:'s1'},{label:'Registered',date:'2026-10-10',source:'s1'},{label:'Proposal submitted',date:'2026-10-12',source:'s3'},{label:'Shortlisted',date:'2026-10-13',source:'s4'}],sources:['s1','s2','s3','s4'],created:'2026-10-08T08:00:00'},{id:'e2',name:'Build for Good Challenge',organizer:'Civic Lab',category:'Competition',stage:'Registered',url:'',registrationId:'',dates:{'Submission deadline':'2026-10-19','Final round':'2026-10-24'},history:[],journey:[{label:'Discovered',date:'2026-10-09',source:'s5'},{label:'Registered',date:'2026-10-12',source:'s5'}],sources:['s5'],created:'2026-10-09T11:00:00'},{id:'e3',name:'Design Futures Workshop',organizer:'Creative Campus',category:'Workshop',stage:'Discovered',url:'',registrationId:'',dates:{'Registration deadline':'2026-10-21','Workshop':'2026-10-28'},history:[],journey:[{label:'Discovered',date:'2026-10-11',source:'s6'}],sources:['s6'],created:'2026-10-11T10:00:00'}],sources:[{id:'s1',title:'Registration confirmation (sample)',type:'Email',date:'2026-10-10T09:00:00',text:'Northstar Hackathon 2026 registration confirmed. Registration ID NST-2048. Proposal deadline: October 15, 2026.',reliability:'Sample data'},{id:'s2',title:'Deadline extension (simulated)',type:'Organizer announcement',date:'2026-10-13T09:00:00',text:'Northstar Hackathon 2026: proposal deadline extended to October 17, 2026. Registration ID NST-2048.',reliability:'Simulated update'},{id:'s3',title:'Submission receipt (sample)',type:'Email',date:'2026-10-12T18:00:00',text:'Northstar Hackathon 2026 proposal submitted. Registration ID NST-2048.',reliability:'Sample data'},{id:'s4',title:'Shortlisting notice (sample)',type:'Email',date:'2026-10-13T13:00:00',text:'Congratulations. Your Northstar Hackathon 2026 team has been shortlisted. Registration ID NST-2048.',reliability:'Sample data'},{id:'s5',title:'Registration note (sample)',type:'Shared message',date:'2026-10-12T10:00:00',text:'Build for Good Challenge registration confirmed. Submission deadline October 19, 2026. Final round October 24, 2026.',reliability:'Sample data'},{id:'s6',title:'Workshop poster text (sample)',type:'Poster or screenshot text',date:'2026-10-11T12:00:00',text:'Design Futures Workshop by Creative Campus. Registration deadline October 21, 2026. Workshop October 28, 2026.',reliability:'Sample data'}],review:[]});
let state=load(),view='overview',selected=null,filter='All';
function load(){try{let x=JSON.parse(localStorage.getItem(KEY));return x&&Array.isArray(x.events)?x:seed()}catch{return seed()}}
function save(){localStorage.setItem(KEY,JSON.stringify(state));render()}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>{if(!d)return 'Not known';let x=new Date(d+'T12:00:00');return isNaN(x)?d:x.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})};
const short=d=>{if(!d)return '—';let x=new Date(d+'T12:00:00');return isNaN(x)?d:x.toLocaleDateString('en-US',{month:'short',day:'numeric'})};
const stageClass=s=>s==='Shortlisted'||s==='Completed'?'green':s==='Registered'?'blue':s==='Discovered'?'gray':'orange';
const tag=(s,c)=>`<span class="tag ${c||stageClass(s)}">${esc(s)}</span>`;
const source=id=>state.sources.find(s=>s.id===id);
const allDates=e=>Object.entries(e.dates||{}).filter(([k,v])=>v).sort((a,b)=>a[1].localeCompare(b[1]));
function nextDate(e){let today=new Date().toISOString().slice(0,10);return allDates(e).find(x=>x[1]>=today)||allDates(e).at(-1)}
function counts(){let upcoming=state.events.reduce((n,e)=>n+allDates(e).filter(x=>x[1]>=new Date().toISOString().slice(0,10)).length,0);return {events:state.events.length,upcoming,changes:state.events.reduce((n,e)=>n+e.history.length,0),review:state.review.length}}
function eventCard(e){let n=nextDate(e);return `<article class="event-card" data-event="${esc(e.id)}"><div class="event-top"><div><div class="event-title">${esc(e.name)}</div><div class="event-org">${esc(e.organizer||'Organizer not known')} · ${esc(e.category||'Event')}</div></div>${tag(e.stage)}</div><div class="event-bottom"><span>◷ &nbsp;${n?esc(n[0])+': <b>'+short(n[1])+'</b>':'No dated milestone'}</span><i class="dot"></i><span>▤ &nbsp;${e.sources.length} source${e.sources.length===1?'':'s'}</span>${e.history.length?'<i class="dot"></i><span class="due">↗ &nbsp;'+e.history.length+' change'+(e.history.length===1?'':'s')+'</span>':''}</div></article>`}
function activities(){let a=[];state.events.forEach(e=>{e.history.forEach(h=>a.push({title:`${h.field} updated`,desc:`${e.name}: ${short(h.old)} → ${short(h.value)}`,date:h.at,orange:true}));e.journey.forEach(j=>a.push({title:`${j.label}`,desc:e.name,date:j.date+'T12:00:00'}))});return a.sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5)}
function overview(){let c=counts();return `<div class="eyebrow">THE BIG PICTURE</div><div class="hero-row"><div><h1>Good morning, student <span style="color:#e6a862">✳</span></h1><p>Every opportunity, update, and next step in one place.</p></div><div class="hero-actions"><button class="button ghost" id="demo-button">▶ &nbsp;View demo flow</button><button class="button primary" id="add-button">+ &nbsp;Import update <span>→</span></button></div></div><div class="stats"><div class="stat"><div class="stat-top">Opportunities <span class="stat-icon">◫</span></div><strong>${c.events}</strong></div><div class="stat"><div class="stat-top">Upcoming milestones <span class="stat-icon">◷</span></div><strong>${c.upcoming}</strong></div><div class="stat"><div class="stat-top">Tracked changes <span class="stat-icon">↗</span></div><strong>${c.changes}</strong></div><div class="stat"><div class="stat-top">Needs your review <span class="stat-icon">◇</span></div><strong>${c.review}</strong></div></div><div class="grid-main"><section class="panel"><div class="panel-head"><div><h2>Your opportunities</h2><p>Active journeys across every source</p></div><button class="text-button" data-view="timeline">View all →</button></div><div class="event-list">${state.events.slice(0,3).map(eventCard).join('')||'<div class="empty"><strong>No opportunities yet</strong>Import a communication to begin.</div>'}</div></section><section class="panel"><div class="panel-head"><div><h2>Recent activity</h2><p>A clear record of what changed</p></div></div><div class="activity">${activities().map(a=>`<div class="activity-row"><div class="activity-icon ${a.orange?'orange':''}">${a.orange?'↗':'✓'}</div><div class="activity-text"><strong>${esc(a.title)}</strong>${esc(a.desc)}<div class="activity-time">${fmt(a.date.slice(0,10))}</div></div></div>`).join('')||'<div class="empty">No activity yet.</div>'}</div></section></div><div class="banner"><div><h3>Information changes. Your timeline keeps up.</h3><p>Import an organizer message to compare dates, see source evidence, and approve the update.</p></div><button id="banner-add">Import an update →</button></div>`}
function timeline(){let list=state.events.filter(e=>filter==='All'||e.stage===filter);return `<div class="eyebrow">LIVING TIMELINE</div><div class="hero-row"><div><h1>Your event journey</h1><p>One evolving record for every opportunity you choose to track.</p></div><button class="button primary" id="add-button">+ &nbsp;Import update <span>→</span></button></div><div class="section-title"><div><h2>Opportunities <span style="color:#aab5ac">${state.events.length}</span></h2><p>Select an event to inspect milestones, changes, and evidence.</p></div><div class="filter-row">${['All','Discovered','Registered','Shortlisted'].map(f=>`<button class="filter ${filter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div></div><section class="panel"><div class="event-list">${list.map(eventCard).join('')||'<div class="empty"><strong>No events in this view</strong>Try another status.</div>'}</div></section>`}
function detail(e){let standard=e.category==='Workshop'?['Discovered','Registered','Attended','Completed']:['Discovered','Registered','Proposal submitted','Shortlisted','Participation confirmed','Final event','Completed'];let j=[...new Set([...standard,...e.journey.map(x=>x.label)])];return `<button class="back" id="back-button">← Back to timeline</button><div class="detail-cover"><div class="eyebrow">${esc(e.category||'OPPORTUNITY')} · LIVING RECORD</div><h2>${esc(e.name)}</h2><p>${esc(e.organizer||'Organizer not known')}</p><div class="detail-meta"><span>${esc(e.stage)}</span><span>${e.sources.length} sources</span><span>${e.history.length} tracked changes</span></div></div><div class="detail-grid"><div><section class="panel detail-section"><h3>Participation journey</h3><div class="journey">${j.map(x=>{let hit=e.journey.find(k=>k.label===x);return `<div class="journey-row"><div class="journey-dot ${hit?'':'pending'}">${hit?'✓':'·'}</div><div><strong>${esc(x)}</strong><p>${hit?fmt(hit.date)+' · '+esc(source(hit.source)?.title||'Student action'):'Awaiting evidence or student action'}</p></div></div>`}).join('')}</div></section><section class="panel detail-section" style="margin-top:20px"><h3>Change history</h3>${e.history.length?e.history.slice().reverse().map(h=>`<div class="change-box"><strong>${esc(h.field.toUpperCase())} UPDATED</strong><div class="change-values"><s>${short(h.old)}</s><span>→</span><span>${short(h.value)}</span></div><p>${esc(source(h.source)?.title||'Source')} · ${fmt(h.at.slice(0,10))} · Student reviewed</p></div>`).join(''):'<div class="empty">No changes recorded yet.</div>'}</section></div><div><section class="panel detail-section"><h3>Current facts</h3><div class="fact-row"><span>Participation status</span><strong>${esc(e.stage)}</strong></div>${allDates(e).map(([k,v])=>`<div class="fact-row"><span>${esc(k)}</span><strong>${fmt(v)}</strong></div>`).join('')}<div class="fact-row"><span>Registration ID</span><strong>${esc(e.registrationId||'Not known')}</strong></div>${e.url?`<div class="fact-row"><span>Event link</span><strong><a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">Open ↗</a></strong></div>`:''}</section><section class="panel detail-section" style="margin-top:20px"><h3>Evidence & sources</h3>${e.sources.map(id=>{let s=source(id);return s?`<div class="source-row"><div class="source-glyph">▤</div><div><strong>${esc(s.title)}</strong><p>${esc(s.type)} · ${fmt(s.date.slice(0,10))} · ${esc(s.reliability)}</p></div></div>`:''}).join('')}<div class="notice">A source reference shows where a fact came from. Imported text is student provided and is not independently authenticated.</div></section></div></div>`}
function review(){return `<div class="eyebrow">REVIEW QUEUE</div><div class="hero-row"><div><h1>Updates that need you</h1><p>Ambiguous matches and changed facts wait here until you decide.</p></div><button class="button primary" id="add-button">+ &nbsp;Import update <span>→</span></button></div><div class="notice">CampusRelay never silently merges an uncertain communication or replaces an existing date. Review the proposed source and changes first.</div>${state.review.length?state.review.map(r=>`<section class="panel review-card"><div style="display:flex;justify-content:space-between;gap:10px"><div><h3>${esc(r.title)}</h3><p>${esc(r.reason)}</p></div>${tag(r.matchLabel,'orange')}</div>${r.eventId?`<p><strong>Suggested event:</strong> ${esc(state.events.find(e=>e.id===r.eventId)?.name||'Unknown')}</p>`:''}${r.changes?.length?r.changes.map(c=>`<div class="result-line"><span>${esc(c.field)}</span><strong>${c.old?short(c.old)+' → ':''}${short(c.value)}</strong></div>`).join(''):''}${r.stage?`<div class="result-line"><span>Participation stage</span><strong>${esc(r.stage)}</strong></div>`:''}<div class="review-actions"><button class="button primary" data-approve="${esc(r.id)}">${r.eventId?'Apply to event':'Create event'} →</button><button class="button ghost" data-dismiss="${esc(r.id)}">Dismiss</button></div></section>`).join(''):'<section class="panel empty"><strong>All caught up</strong>New uncertain matches and proposed changes will appear here.</section>'}`}
function sources(){return `<div class="eyebrow">EVIDENCE LIBRARY</div><div class="hero-row"><div><h1>Source records</h1><p>Trace every imported communication back to the event it informed.</p></div><button class="button primary" id="add-button">+ &nbsp;Import update <span>→</span></button></div><div class="notice">Sample and simulated records are labeled. Your imports remain in this browser and should be reviewed before being treated as accurate.</div><section class="panel detail-section">${state.sources.slice().reverse().map(s=>`<div class="source-row"><div class="source-glyph">▤</div><div><strong>${esc(s.title)}</strong><p>${esc(s.type)} · ${fmt(s.date.slice(0,10))} · ${esc(s.reliability)}</p><div style="color:#6f7e71;font-size:11px;line-height:1.5;margin-top:6px">${esc(s.text.slice(0,230))}${s.text.length>230?'…':''}</div></div></div>`).join('')}</section>`}
function render(){document.getElementById('review-count').textContent=state.review.length;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.getElementById('crumb-current').textContent=selected?'Event details':({overview:'Overview',timeline:'Living timeline',review:'Review queue',sources:'Sources'}[view]);document.getElementById('today-label').textContent=new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'});document.getElementById('content').innerHTML=selected?detail(state.events.find(e=>e.id===selected)||state.events[0]):({overview,timeline,review,sources}[view]||overview)()}
document.addEventListener('click',e=>{let t=e.target.closest('[data-view],[data-event],[data-filter],[data-approve],[data-dismiss],#add-button,#banner-add,#demo-button,#back-button,#reset-button,#process-import');if(!t)return;if(t.dataset.view){view=t.dataset.view;selected=null;render()}else if(t.dataset.event){selected=t.dataset.event;render()}else if(t.dataset.filter){filter=t.dataset.filter;render()}else if(t.id==='add-button'||t.id==='banner-add'){document.getElementById('import-dialog').showModal()}else if(t.id==='back-button'){selected=null;view='timeline';render()}else if(t.id==='demo-button'){selected='e1';render()}else if(t.id==='reset-button'){if(confirm('Reset this browser workspace to the CampusRelay sample?')){state=seed();selected=null;view='overview';save()}}else if(t.id==='process-import'){processImport()}else if(t.dataset.approve){approve(t.dataset.approve)}else if(t.dataset.dismiss){state.review=state.review.filter(r=>r.id!==t.dataset.dismiss);save()}});
const month='january february march april may june july august september october november december'.split(' ');
function parseDate(s){s=s.trim();let d;if(/^\d{4}-\d{2}-\d{2}$/.test(s))return s;let x=s.match(/(\d{1,2})[\s\/-](\d{1,2})[\s\/-](20\d{2})/);if(x){let a=+x[1],b=+x[2];d=new Date(+x[3],b-1,a);return `${x[3]}-${String(b).padStart(2,'0')}-${String(a).padStart(2,'0')}`}let m=s.match(new RegExp(`(${month.join('|')})\\s+(\\d{1,2})(?:st|nd|rd|th)?(?:,?\\s*(20\\d{2}))?`,'i'));if(m){let y=+(m[3]||new Date().getFullYear());return `${y}-${String(month.indexOf(m[1].toLowerCase())+1).padStart(2,'0')}-${m[2].padStart(2,'0')}`}m=s.match(new RegExp(`(\\d{1,2})(?:st|nd|rd|th)?\\s+(${month.join('|')})(?:,?\\s*(20\\d{2}))?`,'i'));if(m){let y=+(m[3]||new Date().getFullYear());return `${y}-${String(month.indexOf(m[2].toLowerCase())+1).padStart(2,'0')}-${m[1].padStart(2,'0')}`}return null}
function extract(text){let lines=text.split(/[\n.!?]+/).map(x=>x.trim()).filter(Boolean),data={dates:{},stage:null,name:null,organizer:null,registrationId:null,url:null};let url=text.match(/https?:\/\/[^\s)]+/);if(url)data.url=url[0].replace(/[,.]$/,'');let rid=text.match(/(?:registration|application|team)\s*(?:id|#|number)\s*[:#-]?\s*([A-Z0-9-]{4,})/i);if(rid)data.registrationId=rid[1];let named=text.match(/(?:for|at|join|welcome to)\s+([A-Z][\w&' -]{4,55}(?:Hackathon|Challenge|Competition|Workshop|Summit|Fest|Conference))/i)||text.match(/([A-Z][\w&' -]{3,55}(?:Hackathon|Challenge|Competition|Workshop|Summit|Fest|Conference)(?:\s*20\d{2})?)/i);if(named)data.name=named[1].trim();let org=text.match(/(?:organized by|hosted by|by)\s+([A-Z][\w&' -]{3,45})/i);if(org)data.organizer=org[1].trim();let patterns=[['Registration deadline',/registration\s+(?:deadline|closes?|ends?)/i],['Proposal deadline',/proposal\s+(?:submission\s+)?(?:deadline|due|closes?|ends?)/i],['Submission deadline',/(?:submission|submit|deliverable)\s+(?:deadline|due|closes?|ends?)/i],['Final round',/(?:final\s+round|finals)/i],['Workshop',/workshop\s+(?:date|on)/i],['Event date',/(?:event|hackathon|competition)\s+(?:date|on)/i]];for(let line of lines){for(let [label,re] of patterns){if(re.test(line)){let d=parseDate(line);if(d)data.dates[label]=d}}}if(/not\s+shortlisted|unfortunately.*not\s+selected/i.test(text))data.stage='Not shortlisted';else if(/shortlisted|qualified|selected for (?:the )?(?:next|final)/i.test(text))data.stage='Shortlisted';else if(/(?:submission|proposal).{0,25}(?:received|submitted|confirmed)|thank you for submitting/i.test(text))data.stage='Proposal submitted';else if(/registration.{0,35}(?:confirmed|successful|complete)|you are registered/i.test(text))data.stage='Registered';else if(/participation.{0,20}confirmed/i.test(text))data.stage='Participation confirmed';else if(/cancelled|canceled/i.test(text))data.stage='Cancelled';return data}
function match(data,text){let ranked=state.events.map(e=>{let score=0,why=[];if(data.registrationId&&e.registrationId&&data.registrationId.toLowerCase()===e.registrationId.toLowerCase()){score+=100;why.push('Matching registration ID')}if(data.url&&e.url&&data.url===e.url){score+=100;why.push('Matching official URL')}let name=e.name.toLowerCase(),t=text.toLowerCase();if(t.includes(name)){score+=65;why.push('Event name appears in message')}else if(data.name){let words=data.name.toLowerCase().split(/\W+/).filter(w=>w.length>3);let overlap=words.filter(w=>name.includes(w)).length;score+=Math.min(overlap*12,36);if(overlap)why.push('Similar event name')}if(data.organizer&&e.organizer&&e.organizer.toLowerCase().includes(data.organizer.toLowerCase())){score+=15;why.push('Organizer matches')}return {id:e.id,score,why}}).sort((a,b)=>b.score-a.score);return ranked}
function processImport(){let text=document.getElementById('source-text').value.trim(),type=document.getElementById('source-type').value,title=document.getElementById('source-title').value.trim()||type+' · '+new Date().toLocaleDateString();if(text.length<20){alert('Please paste at least a sentence of event information.');return}let data=extract(text),matches=match(data,text),best=matches[0],second=matches[1],clear=best&&best.score>=60&&(!second||best.score-second.score>=25);let src={id:'s'+Date.now(),title,type,date:new Date().toISOString(),text,reliability:'Student-provided'};state.sources.push(src);let proposed={id:'r'+Date.now(),title,source:src.id,eventId:clear?best.id:null,reason:clear?`High match: ${best.why.join(', ')}. Review proposed facts before applying.`:best?.score>15?'Several events may fit this communication. Choose a destination in review.':'No clear existing event match. Review before creating a new event.',matchLabel:clear?'High match':'Uncertain match',data,stage:data.stage,changes:[]};if(clear){let ev=state.events.find(e=>e.id===best.id);proposed.changes=Object.entries(data.dates).filter(([field,v])=>ev.dates[field]!==v).map(([field,v])=>({field,old:ev.dates[field]||null,value:v}))}state.review.push(proposed);document.getElementById('import-dialog').close();document.getElementById('source-text').value='';document.getElementById('source-title').value='';save();showResult(proposed,matches)}
function showResult(r,matches){let box=document.getElementById('result-content');let hasFacts=Object.keys(r.data.dates).length||r.data.stage||r.data.name;box.innerHTML=`<div class="modal-head"><div><div class="eyebrow">IMPORT ANALYZED</div><h2>${r.eventId?'We found a likely match':'This needs your review'}</h2><p>${esc(r.reason)}</p></div><button class="close" id="close-result">×</button></div>${r.eventId?`<div class="result-line"><span>Matched event</span><strong>${esc(state.events.find(e=>e.id===r.eventId)?.name)}</strong></div>`:''}${r.data.name?`<div class="result-line"><span>Detected name</span><strong>${esc(r.data.name)}</strong></div>`:''}${Object.entries(r.data.dates).map(([k,v])=>`<div class="result-line"><span>${esc(k)}</span><strong>${short(v)}</strong></div>`).join('')}${r.stage?`<div class="result-line"><span>Participation</span><strong>${esc(r.stage)}</strong></div>`:''}${!hasFacts?'<div class="notice warn">No reliable date or status was extracted. Keep the source for review and enter a clearer announcement if available.</div>':''}${!r.eventId&&matches.filter(m=>m.score>15).length?`<div style="margin-top:17px;font-weight:800;font-size:12px">Possible events</div>${matches.filter(m=>m.score>15).slice(0,3).map(m=>`<div class="candidate"><div><strong>${esc(state.events.find(e=>e.id===m.id)?.name)}</strong><small>${esc(m.why.join(', '))}</small></div><button data-link="${esc(m.id)}" data-review="${esc(r.id)}">Link here</button></div>`).join('')}`:''}<div class="modal-actions"><button class="button primary" id="go-review">Review proposal →</button></div>`;document.getElementById('result-dialog').showModal()}
document.getElementById('result-dialog').addEventListener('click',e=>{let t=e.target.closest('#close-result,#go-review,[data-link]');if(!t)return;if(t.dataset.link){let r=state.review.find(x=>x.id===t.dataset.review);r.eventId=t.dataset.link;r.matchLabel='Student selected';r.reason='You selected the matching event. Review extracted facts before applying.';let ev=state.events.find(x=>x.id===r.eventId);r.changes=Object.entries(r.data.dates).filter(([f,v])=>ev.dates[f]!==v).map(([field,value])=>({field,old:ev.dates[field]||null,value}));save()}document.getElementById('result-dialog').close();view='review';selected=null;render()});
function approve(id){let r=state.review.find(x=>x.id===id);if(!r)return;if(!r.eventId){let name=r.data.name||prompt('Name this event:');if(!name)return;let e={id:'e'+Date.now(),name,organizer:r.data.organizer||'Organizer not known',category:/workshop/i.test(name)?'Workshop':/hackathon/i.test(name)?'Hackathon':'Event',stage:r.stage||'Discovered',url:r.data.url||'',registrationId:r.data.registrationId||'',dates:r.data.dates,history:[],journey:[{label:r.stage||'Discovered',date:new Date().toISOString().slice(0,10),source:r.source}],sources:[r.source],created:new Date().toISOString()};state.events.unshift(e);selected=e.id;view='timeline'}else{let e=state.events.find(x=>x.id===r.eventId);if(!e)return;for(let c of r.changes||[]){if(c.old)e.history.push({field:c.field,old:c.old,value:c.value,source:r.source,at:new Date().toISOString()});e.dates[c.field]=c.value}if(r.stage&&r.stage!==e.stage){e.stage=r.stage;e.journey.push({label:r.stage,date:new Date().toISOString().slice(0,10),source:r.source})}if(r.data.registrationId&&!e.registrationId)e.registrationId=r.data.registrationId;if(r.data.url&&!e.url)e.url=r.data.url;if(!e.sources.includes(r.source))e.sources.push(r.source);selected=e.id;view='timeline'}state.review=state.review.filter(x=>x.id!==id);save()}
render();
